// Minimal mock contracts to satisfy interfaces
contract IERC20Mock {
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public balanceOf;

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function setAllowance(address owner, address spender, uint256 amount) external {
        allowance[owner][spender] = amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function totalSupply() external view returns (uint256) { return 0; }
}

contract IRewardRouterV2Mock {
    uint256 private _returnAmount;

    function mintAndStakeGlp(address, uint256, uint256, uint256) external returns (uint256) {
        return _returnAmount;
    }

    function setMintAndStakeGlpReturn(uint256 amount) external {
        _returnAmount = amount;
    }
}

contract IVaultMock {
    function getMinPrice(address) external view returns (uint256) {
        return 1e18; // 1 USD per unit
    }
}

contract IGlpManagerMock {
    address private _vault;

    function vault() external view returns (address) {
        return _vault;
    }

    function setVault(address v) external {
        _vault = v;
    }
}

contract IDnGmxJuniorVaultMock {
    uint256 private _depositReturn;
    mapping(address => uint256) public balanceOf;

    function deposit(uint256 amount, address receiver) external returns (uint256) {
        balanceOf[receiver] = amount; // simplified
        return _depositReturn;
    }

    function setDepositReturn(uint256 shares) external {
        _depositReturn = shares;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        // No ownable check; just transfer shares (simplified)
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function redeem(uint256 shares, address receiver, address owner) external returns (uint256) { return 0; }
    function harvestFees() external {}
}

